import type { CheckReport } from "@/agent/checks";

export type Channel = "instagram_comment" | "facebook_comment" | "whatsapp" | "manual_import";

export interface Variant {
  id: string;
  label: string; // e.g. "22 inches" or "Burgundy"
  priceNaira: number;
  stock: number;
}

export interface Product {
  id: string;
  name: string;
  description: string;
  category: string;
  tags: string[];
  variants: Variant[];
  /** Catalogue image (data URL in the demo store). */
  imageUrl?: string;
  /** True when the catalogue image was generated by Muse Image from the vendor's photo. */
  imageIsAiEnhanced?: boolean;
}

export interface DeliveryZone {
  city: string;
  aliases: string[];
  feeNaira: number;
  eta: string;
}

export interface Post {
  id: string;
  channel: Channel;
  caption: string;
  productIds: string[];
  postedAt: string;
}

export interface Vendor {
  id: string;
  businessName: string;
  whatsappNumber: string;
  paymentNote: string; // how the vendor wants to be paid; the agent never invents account details
  tone: string;
}

export interface Enquiry {
  id: string;
  channel: Channel;
  text: string;
  /** Instagram username, Facebook name, or WhatsApp number (wa_id). Replies on WhatsApp go to this. */
  authorHandle?: string;
  authorName?: string;
  postId?: string;
  receivedAt: string;
  transcribedFromVoice?: boolean;
  isDemo?: boolean;
}

/**
 * new        – arrived, not yet triaged or drafted
 * drafted    – a reply draft is waiting for the vendor
 * escalated  – needs the vendor personally (complaint, refund, custom request)
 * replied    – the vendor approved and sent (or copied) a reply
 * ignored    – casual engagement or spam, nothing to answer
 */
export type EnquiryStatus = "new" | "drafted" | "escalated" | "replied" | "ignored";

export interface DraftMeta {
  steps: Array<{ tool: string; args: unknown; result: unknown }>;
  groundedAmounts: number[];
  grounding: { ok: boolean; ungrounded: number[] };
  repaired: boolean;
  orderRefs: string[];
  escalated: boolean;
  model: string;
  usage: { prompt_tokens: number; completion_tokens: number };
  /** "agent" for Muse Spark drafts, "template" for deterministic order confirmations. */
  source: "agent" | "template";
  /** How many earlier messages from this chat the agent was given (customer messages + sent replies). */
  historyMessages?: number;
  /** Independent checks run in code after the agent finished (see src/agent/checks.ts). */
  checks?: CheckReport;
  /** Why autopilot did or didn't send this draft by itself. */
  autopilot?: { eligible: boolean; reason: string };
}

export interface EnquiryRecord extends Enquiry {
  intent?: string;
  language?: string;
  englishGloss?: string;
  confidence?: number;
  priority: number;
  status: EnquiryStatus;
  draftReply?: string;
  draftMeta?: DraftMeta;
  replyText?: string;
  repliedAt?: string;
  orderRef?: string;
  /** Sent by autopilot rather than approved by the vendor. */
  autoSent?: boolean;
}

/**
 * draft      – the agent created it and sent the buyer a checkout link
 * confirmed  – the buyer tapped the link and messaged the order ref on WhatsApp
 * paid       – the vendor confirmed payment (stock is deducted here)
 * cancelled  – the vendor cancelled it
 */
export type OrderStatus = "draft" | "confirmed" | "paid" | "cancelled";

export interface Order {
  ref: string; // short reference code shared with the buyer, e.g. SA-7K2P
  productId: string;
  variantId: string;
  quantity: number;
  unitPriceNaira: number;
  deliveryFeeNaira: number;
  totalNaira: number;
  city?: string;
  customerHandle?: string;
  channel: Channel;
  sourcePostId?: string;
  sourceEnquiryId?: string;
  status: OrderStatus;
  createdAt: string;
  /** Times the buyer opened the checkout link. Funnel: enquiry → link clicked → order confirmed. */
  linkClicks: number;
  firstClickedAt?: string;
  confirmedAt?: string;
  paidAt?: string;
  isDemo?: boolean;
}
